import{_ as s,o as t,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p="/assets/a0b9c5107e4ffe6f.Cd55EHGK.png",i="/assets/48e0cc29e8ce5c3a.B9-5EYct.png",a="/assets/eb0f0d239d14d318.BgNV07C6.png",n="/assets/f92aea1702b36fc7.BYkY1uJV.png",c="/assets/74a3ae0bb79518bc.CSk9myLi.png",C=JSON.parse('{"title":"Windows远程桌面出现CredSSP加密数据修正问题解决方案","description":"","frontmatter":{"title":"Windows远程桌面出现CredSSP加密数据修正问题解决方案"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/windows/rdp-credssp-encryption-fix.md","filePath":"ops-knowledge-base/operating-system/windows/rdp-credssp-encryption-fix.md","lastUpdated":1788259091000}'),d={name:"ops-knowledge-base/operating-system/windows/rdp-credssp-encryption-fix.md"};function l(m,e,_,w,S,P){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>问题现象：通过远程桌面连接Windows实例时，出现错误提示“出现身份验证错误，要求的函数不受支持”。</p><p><img src="'+p+'" alt=""></p><p>问题原因：</p><p>微软官方于2018年5月，更新了凭据安全支持提供程序协议（CredSSP）相关补丁和身份验证请求方式</p><p>默认情况下，安装此更新后，修补的本地电脑无法与未修补的实例进行通信</p><p>解决方案：</p><p>根据实际情况，参考以下三种解决方案：</p><p>方案一：在本地PC上运行以下命令</p><p>1.在本地PC上用管理员权限打开CMD窗口运行以下命令</p><p>reg add &quot;HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP\\Parameters&quot; /v AllowEncryptionOracle /t REG_DWORD /d 2 /f</p><p>方案二：实例允许远程桌面连接</p><p>1.通过VNC连接进入Windows系统，点击开始菜单，右键单击这台电脑 - 属性</p><p><img src="'+i+'" alt=""></p><ol start="3"><li>2.在控制面板主页上，单击远程设置</li></ol><p><img src="'+a+'" alt=""></p><ol start="4"><li>3.在远程页签下，取消勾选仅允许运行使用网络级别身份验证的远程桌面的计算机连接（建议），然后单击确定。</li></ol><p><img src="'+n+'" alt=""></p><p>方案三：修改注册表</p><p>1.通过VNC连接进入Windows系统</p><p>2.单击右下角“Windows PowerShell”打开后执行如下命令，以管理员身份运行Windows PowerShell脚本</p><p><img src="'+c+'" alt=""></p><ul><li><p>New-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System -Name CredSSP -Force</p></li><li><p>New-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP -Name Parameters -Force</p></li><li><p>Get-Item -Path HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP\\Parameters | New-ItemProperty -Name AllowEncryptionOracle -Value 2 -PropertyType DWORD -Force</p></li></ul><p>3.重启机器后生效</p>',23)])])}const g=s(d,[["render",l]]);export{C as __pageData,g as default};
